/// <summary>
/// This is the data contract class for ER inventory non conformance report
/// </summary>
[DataContractAttribute]
public class AVAInventNonConformanceReportContractCls extends ERFormatMappingRunBaseContract
{
    str packedQuery;
    public boolean     printToMemory;

}

Method.Source:
/// <summary>
/// parm method for packedQuery
/// </summary>
/// <param name = "_packedQuery">str</param>
/// <returns>str</returns>
[DataMemberAttribute, AifQueryTypeAttribute('_packedQuery', queryStr(AVAERNonConformanceQuery))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;

    return packedQuery;
}

// This method unpacks the query and returns it as query object.
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

// This method takes a query object, encodes it and stores the packed query.
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// initFromArgs method
/// </summary>
/// <param name = "_args">Args</param>
public void initFromArgs(Args _args)
{
    FormRun formRun = _args.caller();
    FormDataSource fd_inventNonConformanceTable = formRun.dataSource();
    MultiSelectionHelper helper = MultiSelectionHelper::construct();
    InventNonConformanceTable nonConformanceTable;
    Query query = fd_inventNonConformanceTable.query();
    QueryBuildDataSource qbdsInventNonConformance = query.dataSourceTable(tablenum(InventNonConformanceTable));
    QueryBuildRange qbrNonConformanceId;

    qbrNonConformanceId = SysQuery::findOrCreateRange(qbdsInventNonConformance, FieldNum(InventNonConformanceTable, InventNonConformanceId));
    qbrNonConformanceId.value("");

    helper.parmDatasource(fd_inventNonConformanceTable);

    nonConformanceTable = helper.getFirst();
    while (nonConformanceTable.RecId != 0)
    {
        qbrNonConformanceId.value(queryRangeConcat(qbrNonConformanceId.value(), nonConformanceTable.InventNonConformanceId));
        nonConformanceTable = helper.getNext();
    }

    this.setQuery(query);
}
